// Exact hundredths, fixed ten-field schema, no DOM dependencies.
export const fields=['width','height','paddingTop','paddingRight','paddingBottom','paddingLeft','borderTop','borderRight','borderBottom','borderLeft'];
export const defaults=()=>({width:'200',height:'120',paddingTop:'10',paddingRight:'20',paddingBottom:'10',paddingLeft:'20',borderTop:'2',borderRight:'2',borderBottom:'2',borderLeft:'2'});
export function parse(raw,key){if(typeof raw!=='string')return{error:'SCHEMA'};if(raw.length>16)return{error:'LENGTH'};const s=raw.replace(/^[\t\n\r ]+|[\t\n\r ]+$/g,'');if(!/^[0-9]+(?:\.[0-9]{1,2})?$/.test(s))return{error:'GRAMMAR'};const [a,b='']=s.split('.');const q=BigInt(a)*100n+BigInt(b.padEnd(2,'0'));if(key.startsWith('border')&&q%100n!==0n)return{error:'INTEGER'};const max=key.startsWith('border')?2000n:key.startsWith('padding')?10000n:60000n;if(q>max)return{error:'RANGE'};return{value:Number(q)};}
export const canonical=q=>`${Math.floor(q/100)}${q%100?'.'+String(q%100).padStart(2,'0').replace(/0+$/,''):''}`;
export function axis(D,P,B,mode){const content=mode==='content-box'?D:Math.max(0,D-P-B);return Object.freeze({declared:D,content,padding:content+P,border:content+P+B,warning:content+P+B>D});}
export function serialize(v,mode){if(!['content-box','border-box'].includes(mode))throw Error('mode');const sides=pre=>['Top','Right','Bottom','Left'].map(s=>canonical(v[pre+s])+'px').join(' ');return`.sample {\n  box-sizing: ${mode};\n  width: ${canonical(v.width)}px;\n  height: ${canonical(v.height)}px;\n  padding: ${sides('padding')};\n  border-style: solid;\n  border-width: ${sides('border')};\n  border-color: #334155;\n  margin: 0;\n}\n`;}
export function calculate(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))return{errors:[{field:'width',code:'SCHEMA'}]};const d=Object.getOwnPropertyDescriptors(raw);if(Reflect.ownKeys(d).length!==10||fields.some(k=>!d[k]||!('value'in d[k])||typeof d[k].value!=='string'))return{errors:[{field:'width',code:'SCHEMA'}]};const v={},errors=[];for(const k of fields){const p=parse(raw[k],k);if(p.error)errors.push({field:k,code:p.error});else v[k]=p.value;}if(errors.length)return{errors};const panels={};for(const mode of ['content-box','border-box'])panels[mode]=Object.freeze({x:axis(v.width,v.paddingLeft+v.paddingRight,v.borderLeft+v.borderRight,mode),y:axis(v.height,v.paddingTop+v.paddingBottom,v.borderTop+v.borderBottom,mode),css:serialize(v,mode)});return Object.freeze({values:Object.freeze(v),panels:Object.freeze(panels)});}
export const initialState=()=>({raw:defaults(),locale:'zh',status:'valid',snapshot:calculate(defaults()),errors:[]});
export function reduce(s,a){if(a.type==='language')return{...s,locale:a.locale};if(a.type==='reset')return{...initialState(),locale:s.locale};if(a.type==='edit')return{...s,raw:{...s.raw,[a.field]:a.value},status:'dirty',snapshot:null,errors:[]};if(a.type==='generate'){const r=calculate(s.raw);return r.errors?{...s,status:'error',snapshot:null,errors:r.errors}:{...s,status:'valid',snapshot:r,errors:[]};}return s;}
